/* Violet Orb — self-contained WebGL custom element. No external dependencies. */
(() => {
  'use strict';
  if (customElements.get('violet-orb')) return;
  const VERTEX = "attribute vec2 aPosition;\nvoid main() { gl_Position = vec4(aPosition, 0.0, 1.0); }\n";
  const FRAGMENT = "precision highp float;\nuniform vec2 uResolution;\nuniform float uTime;\nuniform float uBake;\nuniform sampler2D uSource;\nuniform sampler2D uSurface;\nconst float PI = 3.141592653589793;\n\nvec3 rotateAxis(vec3 p, vec3 axis, float angle) {\n  return p * cos(angle) + cross(axis, p) * sin(angle)\n    + axis * dot(axis, p) * (1.0 - cos(angle));\n}\n\nvec3 material(vec3 q) {\n  // Object-space projection carries the selected surface continuously around\n  // both hemispheres. It has no UV seam and never drags a baked rim across it.\n  return texture2D(uSurface, vec2(0.5 + q.x * 0.495, 0.5 - q.y * 0.495)).rgb;\n}\n\nvoid main() {\n  if (uBake > 0.5) {\n    vec2 uv = gl_FragCoord.xy / uResolution;\n    float theta = (uv.x - 0.5) * 2.0 * PI;\n    float phi = uv.y * PI;\n    vec3 p = vec3(sin(phi) * sin(theta), cos(phi), sin(phi) * cos(theta));\n    gl_FragColor = vec4(material(p), 1.0);\n    return;\n  }\n  vec2 p = (gl_FragCoord.xy * 2.0 - uResolution) / min(uResolution.x, uResolution.y);\n  p /= 0.90;\n  float radius = length(p);\n  float aa = 2.1 / min(uResolution.x, uResolution.y);\n  float alpha = 1.0 - smoothstep(1.0 - aa, 1.0 + aa, radius);\n  if (alpha <= 0.0) { gl_FragColor = vec4(0.0); return; }\n  vec3 n = normalize(vec3(p, sqrt(max(0.0, 1.0 - dot(p,p)))));\n  vec3 axis = normalize(vec3(0.12, 1.0, 0.17));\n  vec3 q = rotateAxis(n, axis, -uTime * 2.0 * PI / 12.0);\n  vec3 color = material(q);\n  vec3 light = normalize(vec3(-0.45, 0.70, 1.6));\n  float diffuse = max(0.0, dot(n, light));\n  float bright = smoothstep(0.78, 0.97, max(color.r, max(color.g, color.b)));\n  color *= mix(0.60 + 0.40 * diffuse, 1.0, bright * 0.85);\n  vec3 halfLight = normalize(light + vec3(0.0, 0.0, 1.0));\n  float specular = pow(max(0.0, dot(n, halfLight)), 100.0);\n  color += vec3(0.16, 0.13, 0.22) * specular;\n  float rim = pow(1.0 - max(n.z, 0.0), 3.3);\n  color += vec3(0.24, 0.04, 0.42) * rim;\n  gl_FragColor = vec4(clamp(color, 0.0, 1.0), alpha);\n}\n";
  const SURFACE = "data:image/webp;base64,";
  const POSTER = "data:image/png;base64,";

  class VioletOrb extends HTMLElement {
    static get observedAttributes() { return ['paused', 'duration']; }
    constructor() {
      super();
      this.attachShadow({mode:'open'});
      this.shadowRoot.innerHTML = `<style>
        :host{display:inline-block;position:relative;width:320px;max-width:100%;aspect-ratio:1;vertical-align:middle;contain:layout paint}
        canvas,img{position:absolute;inset:0;display:block;width:100%;height:100%;object-fit:contain}
        img{transition:opacity .18s}canvas{background:transparent}
      </style><canvas part="canvas" aria-hidden="true"></canvas><img part="poster" alt="" draggable="false">`;
      this.canvas=this.shadowRoot.querySelector('canvas');
      this.poster=this.shadowRoot.querySelector('img');this.poster.src=POSTER;
      this.elapsed=0;this.last=0;this.visible=true;this.running=false;this.initialized=false;
      this.motion=matchMedia('(prefers-reduced-motion: reduce)');
      this.onMotion=()=>this.sync();this.onVisibility=()=>this.sync();
      this.tick=this.tick.bind(this);
    }
    connectedCallback() {
      if (!this.hasAttribute('role')) this.setAttribute('role','img');
      if (!this.hasAttribute('aria-label')) this.setAttribute('aria-label','Rotating violet orb');
      this.motion.addEventListener('change',this.onMotion);
      document.addEventListener('visibilitychange',this.onVisibility);
      this.resizeObserver=new ResizeObserver(()=>{this.resize();this.draw();});this.resizeObserver.observe(this);
      this.intersectionObserver=new IntersectionObserver(entries=>{this.visible=entries[0].isIntersecting;this.sync();});this.intersectionObserver.observe(this);
      this.setup();
    }
    disconnectedCallback() {
      this.stop();this.resizeObserver?.disconnect();this.intersectionObserver?.disconnect();
      this.motion.removeEventListener('change',this.onMotion);
      document.removeEventListener('visibilitychange',this.onVisibility);
      if(this.gl){this.gl.deleteTexture(this.texture);this.gl.deleteBuffer(this.buffer);this.gl.deleteProgram(this.program);}
      this.initialized=false;
    }
    attributeChangedCallback(){this.sync();}
    get duration(){const value=Number(this.getAttribute('duration'));return Number.isFinite(value)&&value>0?value:12;}
    // React assigns props to custom elements as properties once the element is
    // upgraded, so a getter-only `duration` threw on every remount.
    set duration(value){if(value==null){this.removeAttribute('duration');return;}this.setAttribute('duration',String(value));}
    play(){this.removeAttribute('paused');}
    pause(){this.setAttribute('paused','');}
    seek(seconds){this.elapsed=Number(seconds)||0;this.draw();}
    setup() {
      const gl=this.canvas.getContext('webgl',{alpha:true,premultipliedAlpha:false,antialias:true,powerPreference:'low-power'});
      if(!gl){this.dispatchEvent(new Event('fallback'));return;}
      this.gl=gl;
      const compile=(type,source)=>{
        const shader=gl.createShader(type);gl.shaderSource(shader,source);gl.compileShader(shader);
        if(!gl.getShaderParameter(shader,gl.COMPILE_STATUS))throw new Error(gl.getShaderInfoLog(shader));
        return shader;
      };
      try {
        const vs=compile(gl.VERTEX_SHADER,VERTEX),fs=compile(gl.FRAGMENT_SHADER,FRAGMENT);
        const program=gl.createProgram();gl.attachShader(program,vs);gl.attachShader(program,fs);gl.linkProgram(program);
        gl.deleteShader(vs);gl.deleteShader(fs);
        if(!gl.getProgramParameter(program,gl.LINK_STATUS))throw new Error(gl.getProgramInfoLog(program));
        this.program=program;gl.useProgram(program);
        this.buffer=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,this.buffer);
        gl.bufferData(gl.ARRAY_BUFFER,new Float32Array([-1,-1,1,-1,-1,1,1,1]),gl.STATIC_DRAW);
        const location=gl.getAttribLocation(program,'aPosition');gl.enableVertexAttribArray(location);gl.vertexAttribPointer(location,2,gl.FLOAT,false,0,0);
        this.resolution=gl.getUniformLocation(program,'uResolution');this.time=gl.getUniformLocation(program,'uTime');
        gl.uniform1f(gl.getUniformLocation(program,'uBake'),0);
        const image=new Image();
        image.onload=()=>{
          if(!this.isConnected)return;
          this.texture=gl.createTexture();gl.activeTexture(gl.TEXTURE0);gl.bindTexture(gl.TEXTURE_2D,this.texture);
          gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL,false);
          gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MIN_FILTER,gl.LINEAR);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MAG_FILTER,gl.LINEAR);
          gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_S,gl.CLAMP_TO_EDGE);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_T,gl.CLAMP_TO_EDGE);
          gl.texImage2D(gl.TEXTURE_2D,0,gl.RGBA,gl.RGBA,gl.UNSIGNED_BYTE,image);
          gl.uniform1i(gl.getUniformLocation(program,'uSurface'),0);
          this.initialized=true;this.resize();this.draw();this.poster.style.opacity='0';
          this.dispatchEvent(new Event('ready'));this.sync();
        };
        image.onerror=()=>this.dispatchEvent(new Event('fallback'));
        image.src=SURFACE;
      } catch(error){console.error('VioletOrb:',error);this.dispatchEvent(new Event('fallback'));}
    }
    resize(){
      const rect=this.getBoundingClientRect();const dpr=Math.min(devicePixelRatio||1,2);
      const width=Math.max(1,Math.min(1024,Math.round(rect.width*dpr)));
      const height=Math.max(1,Math.min(1024,Math.round(rect.height*dpr)));
      if(this.canvas.width!==width||this.canvas.height!==height){this.canvas.width=width;this.canvas.height=height;}
    }
    draw(){
      if(!this.initialized)return;const gl=this.gl;
      gl.useProgram(this.program);gl.viewport(0,0,this.canvas.width,this.canvas.height);
      gl.uniform2f(this.resolution,this.canvas.width,this.canvas.height);
      gl.uniform1f(this.time,(this.elapsed*12/this.duration)%12);
      gl.drawArrays(gl.TRIANGLE_STRIP,0,4);
    }
    sync(){
      const shouldRun=this.isConnected&&this.initialized&&this.visible&&!document.hidden&&!this.motion.matches&&!this.hasAttribute('paused');
      if(shouldRun&&!this.running){this.running=true;this.last=0;this.frame=requestAnimationFrame(this.tick);}
      else if(!shouldRun){this.stop();this.draw();}
    }
    tick(now){
      if(!this.running)return;
      if(this.last)this.elapsed+=Math.min((now-this.last)/1000,.1);
      this.last=now;this.draw();this.frame=requestAnimationFrame(this.tick);
    }
    stop(){this.running=false;this.last=0;cancelAnimationFrame(this.frame);}
  }
  customElements.define('violet-orb',VioletOrb);
})();
